/* Runvis homepage translations — German. One language per file so a
   visitor downloads 1/6 of the dictionary, not all of it. i18n.js
   injects exactly the file it needs and calls RunvisOnDict when it lands. */
(window.RUNVIS_I18N=window.RUNVIS_I18N||{})["de"]={"a11y.langmenu": "Anzeigesprache", "a11y.langname": "Deutsch", "a11y.playing": "Beispielansage läuft", "a11y.skip": "Zum Inhalt springen", "a11y.stopped": "Wiedergabe gestoppt", "a11y.wspause": "Automatischen Wechsel anhalten", "a11y.wsplay": "Automatischen Wechsel einschalten", "alt.phone.detail": "iPhone, Detailansicht eines Werts: Trainingslast (CTL) im 7-Tage-Verlauf, dein 28-Tage-Bereich und die Erklärung des Werts", "alt.phone.glance": "iPhone, unterer Teil des Körper- & Laufberichts: Kacheln für Ausdauer-Trainingsumfang 66/100, Hügelanteil und Hitzebelastung (beide im Status „Lernt noch“), Coach-Bremse, Rekord-Radar des Coachs mit Bestzeiten von 1K bis Halbmarathon, Intensitätsverteilung und Beinbelastung", "alt.phone.hero": "iPhone-Startbildschirm: Die Entscheidung heute lautet Ruhetag (ganz pausieren oder locker spazieren gehen)", "alt.phone.plan": "iPhone-Bildschirm mit dem Wochenplan", "alt.phone.race": "iPhone-Bildschirm mit der Rennzeitprognose", "alt.watch.decision": "Apple Watch Ultra – Runvis, Entscheidung heute: Ring der Laufbereitschaft und die Empfehlung Ruhetag", "alt.watch.evidence": "Apple Watch Ultra – Runvis, Grundlage heute: Schlaf und HRV", "alt.watch.map": "Apple Watch Ultra – Runvis beim Laufen: Live-GPS-Karte mit Distanz, Zeit und Tempo", "alt.watch.pace": "Apple Watch Ultra – Runvis beim Laufen: aktuelles Tempo mit Durchschnitt, Geschwindigkeit, GAP und Steigung", "alt.watch.start": "Apple Watch Ultra – Runvis, Trainingsauswahl: Laufen und Indoor-Lauf", "alt.watch.zone": "Apple Watch Ultra – Runvis, Bogen mit den Pulszonen", "cs.marketing": "(Optional) Ich möchte Neuigkeiten zum Start und Produkt-Updates erhalten.", "cs.purpose": ": Versand deiner TestFlight-Beta-Einladung", "cs.retain": ": wird unverzüglich gelöscht, sobald der Zweck erfüllt ist (Beta-Einladung versendet), spätestens ein Jahr nach der Erhebung", "form.busy": "Die Anmeldung wird gerade vorbereitet. Einen Moment bitte.", "form.fail": "Das Senden hat nicht geklappt. Versuch es bitte gleich noch mal.", "form.mailto": "Per E-Mail anmelden: help@runvis.app", "form.neterr": "Netzwerkfehler. Versuch es bitte gleich noch mal.", "form.novoice": "Dieser Browser kann keine Sprachausgabe abspielen.", "form.ok": "Du bist eingetragen. Sobald der Starttermin feststeht, bekommst du eine Mail an diese Adresse. Wenn die Beta öffnet, gehen die Einladungen in der Reihenfolge der Anmeldungen raus. Eine Bestätigungsmail gibt es nicht, schau also kurz nach, ob die Adresse oben stimmt. Soll die Adresse gelöscht werden, schreib jederzeit an help@runvis.app. Bis dahin: Lauf doch schon mal die 5-km-Demo. 🏃", "form.okcta": "5-km-Demo laufen", "form.sending": "Wird gesendet …", "gpx.ansan": "Ansan-Jarak-Weg", "gpx.banpo": "Banpo Han-River-Park", "gpx.bukak": "Bugak Skyway", "gpx.cheonggyecheon": "Cheonggyecheon-Bach", "gpx.dorimcheon": "Dorimcheon-Bach", "gpx.eungbong": "Eungbongsan-Treppen", "gpx.inwangsan": "Inwangsan-Jarak-Weg", "gpx.naksan": "Naksan-Park, Stadtmauerweg", "gpx.namsan.north": "Namsan-Nordschleife", "gpx.namsan.summit": "Namsan-Gipfelanstieg", "gpx.seoulsup": "Seoul-Forest-Runde", "gpx.tancheon": "Tancheon-Bach", "gpx.yangjaecheon": "Yangjaecheon-Bach", "hero0": "Aktuell sind es 3 Grad bei 60 Prozent Luftfeuchtigkeit. Es ist kalt und die Muskeln werden leicht steif — wir wärmen uns heute etwas länger auf.", "hero1": "In 300 Metern beginnt ein Anstieg über 800 Meter. Durchschnittlich 4 Prozent Steigung. Verkürze den Schritt und halte den Rhythmus.", "hero2": "25 Sekunden schneller als das Ziel", "hero3": "Dein Puls ist auf Zone 3 gefallen. Du erholst dich gut. Nur noch ein Stück.", "hw.vs.cap1": "So sieht die erste Zeile der Tabelle in der App aus: Trainingslast (CTL) im 7-Tage-Verlauf, dein 28-Tage-Bereich und was der Wert bedeutet.", "hw.vs.cap2": "Und so die vierte Zeile: Rennzeitprognose und Tempoplan pro Abschnitt.", "hw.vs.r0a": "Was du dazukaufen musst", "hw.vs.r0b": "Bei Garmin Forerunner oder Coros ist die Uhr selbst das Produkt. Runvis nutzt die Apple Watch, die du schon trägst. Extra bezahlst du nur das Coach-Abo.", "hw.vs.r10a": "Coach-Bremse", "hw.vs.r10b": "Kein Score, sondern ein Budget. Aus deinen Wochenkilometern der letzten 4 abgeschlossenen Wochen ergibt sich, wie viel diese Woche drin ist. Hast du nach einem Lauf Schmerzen notiert, wird das Budget entsprechend kleiner. Die restlichen Kilometer und der Abzug wegen Schmerzen stehen getrennt da. So siehst du sofort, warum es weniger geworden ist.", "hw.vs.r11a": "Rekord-Radar des Coachs", "hw.vs.r11b": "Bei Läufen mit GPS-Route durchsucht Runvis die ganze Aufzeichnung nach dem schnellsten Abschnitt (Bestleistung). Läufe ohne Route werden über das Durchschnittstempo umgerechnet. Auf dem Bildschirm steht, auf welchem Weg eine Bestzeit zustande kam. Gezählt werden die letzten 90 Tage.", "hw.vs.r7a": "Intensitätsverteilung", "hw.vs.r7b": "Hat ein Lauf einen Pulsverlauf und ist dein Maximalpuls wirklich gemessen, teilt Runvis die Laufzeit in drei Bereiche: locker, mittel und hart, mit den Grenzen bei 78 % und 88 % des Maximalpulses. Fehlt der Pulsverlauf oder gibt es nur einen aus dem Alter geschätzten Maximalpuls, entscheidet der Durchschnittspuls des Laufs über den Bereich. Ein Intervalltraining kann dann komplett unter „mittel“ landen. Auf welchem Weg gerechnet wurde, steht auf dem Bildschirm.", "hw.vs.r8a": "Hügelanteil", "hw.vs.r8b": "Gezählt werden nur Läufe mit Anstieg aus den letzten 28 Tagen (mindestens 2). Die Rechnung: Höhenmeter gesamt ÷ Distanz gesamt (m/km). Ab 15 ist das Gelände wellig, ab 40 hügelig. Der Wert bewertet nicht dich, er beschreibt das Gelände, auf dem du gelaufen bist.", "hw.vs.r9a": "Hitzebelastungsindex", "hw.vs.r9b": "Der Index zeigt auf einer Skala von 0 bis 100, wie viel du in den letzten 4 Wochen draußen an Tagen über 22 °C gelaufen bist (bei Fahrenheit-Einstellung der entsprechende Wert). Er erscheint nach 3 Läufen an heißen Tagen und sinkt, wenn du 3 Tage oder länger pausierst. Er zeigt, wie viel Hitze du abbekommen hast, nicht, wie gut dein Körper daran angepasst ist.", "hw.vs.tm": "Garmin, Forerunner und COROS sind Marken der jeweiligen Unternehmen. Runvis steht mit keinem der beiden in Verbindung. Hier stehen nur öffentlich bekannte Fakten. Beide Firmen legen ihre Formeln nicht offen, deshalb gibt es hier keinen Vergleich der Genauigkeit.", "hz.cap": "Dieselben Zonen wie im Rechner unten. So zeigt sie die Uhr beim Laufen.", "meta.desc": "Keine neue Laufuhr nötig: Die Apple Watch, die du schon trägst, wird zum Lauf-Coach. Runvis liest Schlaf und Puls, legt dein Training für heute fest und coacht dich beim Laufen per Stimme, aber nur, wenn es nötig ist. Kein Konto, kein Server.", "meta.ogdesc": "Die Apple Watch an deinem Handgelenk wird zum Lauf-Coach. Morgens steht dein Training fest, beim Laufen sagt er nur, was du gerade brauchst.", "meta.ogalt": "Runvis Karte — You run. We coach.", "meta.ogtitle": "Runvis – Lauf-Coach für die Apple Watch", "meta.title": "Runvis – You run. We coach. Lauf-Coach für die Apple Watch", "n.after.eb": "Nach dem Lauf", "n.after.h2": "Nach dem Lauf<br/>siehst du das Warum hinter den Zahlen", "n.after.h3": "Tippst du einen Wert an, steht er direkt neben deinem üblichen Bereich", "n.after.honest": "<b>Was geschätzt ist, wird auch so genannt.</b> Reichen die Daten nicht, zeigt die App „Lernt noch“ statt einer Zahl. Werte, die sich nicht sicher belegen lassen, sind gar nicht erst eingebaut.", "n.after.l1": "Trainingslast, ACWR und Erholungszeit berechnet Runvis mit veröffentlichten Formeln", "n.after.l2": "In den Laufdetails exportierst du einen Bericht zur KI-Analyse und fügst ihn einfach in die KI ein, die du sonst nutzt", "n.after.l3": "GPX-Export und ein 3D-Überflug deiner Strecke als Video", "n.after.p": "Du siehst auf einen Blick, ob der heutige Wert in deinem üblichen Bereich der letzten 28 Tage liegt und wo er im Vergleich zu vor 4 Wochen steht. Fachbegriffe musst du nicht kennen: Zu jedem Wert gibt es eine Erklärung und den Rechenweg.", "n.after.sub": "Splits, Pulszonen, Laufdynamik und der Coaching-Satz zum Lauf sind gratis. Mit Abo kommen dazu: das Rekord-Radar des Coachs, das in deinen Läufen die schnellsten Abschnitte findet, die geschätzte Laktatschwelle und dein Kilometerbudget für diese Woche.", "n.after.t1": "Detailbericht zum Lauf", "n.after.t1p": "Tempo pro Abschnitt, Verteilung der Pulszonen, Schrittfrequenz und Bodenkontaktzeit im Schnitt. Dazu ein Satz vom Coach zu genau diesem Lauf.", "n.after.t2": "Körperbericht", "n.after.t2p": "Laufbereitschaft, Schlaf, HRV, Ruhepuls, VO₂max. Ein Tipp öffnet den Verlauf und deinen üblichen Bereich der letzten 28 Tage.", "n.after.t3": "Rekord-Radar des Coachs (schnellste Abschnitte · Bestzeiten-Buch)", "n.after.t3p": "Nicht die Endzeit zählt, sondern der schnellste Abschnitt mittendrin: 1 km, 5 km, 10 km und Halbmarathon, herausgesucht aus deinen Läufen der letzten 90 Tage. Dazu siehst du den Abstand zu deiner bisherigen Bestzeit.", "n.after.t4": "Geschätzte Laktatschwelle", "n.after.t4p": "Runvis sucht in deinen Läufen der letzten 90 Tage nach 30-Minuten-Bestleistungen (mindestens 2) und schätzt daraus Schwellentempo und Schwellenpuls. Hast du deinen Maximalpuls eingetragen, zählen nur Abschnitte, die du mit mindestens 85 % davon gelaufen bist.", "n.after.t4h": "Und ohne 30-Minuten-Abschnitt?", "n.after.t4g": "Gibt es keinen 30-Minuten-Abschnitt, rechnet Runvis mit einem 20-Minuten-Abschnitt. Fehlt auch der, nimmt es den Schnitt aus drei Läufen von mindestens 20 Minuten mit mindestens 85 % des Maximalpulses. Das geht nur, wenn du deinen Maximalpuls eingetragen hast. Welcher Weg genutzt wurde, steht immer auf dem Bildschirm.", "n.beta.window": "Einen Starttermin gibt es noch nicht. Sobald er feststeht, erfährst du ihn genau hier. Bis dahin kannst du zwei Dinge tun: dich jetzt eintragen und deinen Platz sichern (im Beta-Build sind alle Coach-Funktionen während der ganzen Beta kostenlos) oder die <a href=\"run.html\">5-km-Demo</a> laufen und schon mal hören, wann und wie der Coach spricht.", "n.faq.a5h": "Was prüfen die Tests genau?", "n.faq.a5g": "Die 4 Übersetzungstabellen der Coach-Stimme müssen Eintrag für Eintrag übereinstimmen, bis hin zur Stelle, an der eine Zahl steht. Außerdem prüfen die Tests, ob jeder Satz aus den Tabellen in der App wirklich vorkommt. Der Test, der einen 45-Minuten-Lauf des iPhone-Coachs nachspielt, läuft in 6 Sprachen, jeweils mit Kilometern und mit Meilen. Passt eine Stelle nicht, schlägt er sofort fehl. Ansagen mit Zahlen (Splits, Anstiege, Tempo, Pulszonen, Trainingsschritte) richten sich in jeder Sprache nach deren Satzstellung.", "a11y.watchstack": "3 Bildschirme der Apple Watch beim Laufen, im Wechsel", "n.after.t5": "Coach-Bremse", "n.after.t5p": "Aus deinem Trainingsumfang der letzten 4 Wochen ergibt sich dein Kilometerbudget für diese Woche. Gibst du Schmerzen an, wird es kleiner.", "n.after.t6": "Runvis-Fitnessindex", "n.after.t6p": "Aus deinen Bestleistungen rechnet Runvis einen Fitnessindex zurück und prognostiziert damit deine Zeiten über verschiedene Distanzen. Direkt daneben steht zum Vergleich der VO₂max-Wert deiner Apple Watch.", "n.beta.cta2": "Beim Start Bescheid bekommen", "n.beta.eb": "Beta-Anmeldung", "n.beta.gpx": "Die GPX-Dateien der 13 Seouler Strecken aus der App. Ohne Anmeldung und ohne die App zu installieren: jetzt herunterladen und auf eine andere Uhr oder in eine Karten-App laden. Die Distanzen stehen in allen 6 Sprachen in km. Eine GPX-Datei hat selbst keine Einheit, die Umrechnung in Meilen übernimmt das Gerät, auf das du sie lädst.", "n.beta.gpxattr": "Strecken aus den Straßen- und Wegedaten von OpenStreetMap, Höhen aus Copernicus DEM / NASA SRTMGL1 (Public Domain). © OpenStreetMap contributors · ODbL 1.0.", "n.beta.gpxh": "Du läufst in Seoul? 13 Strecken als GPX", "n.beta.h2": "Probier Runvis vorab in der Beta aus", "n.beta.nowh": "Was du bis dahin schon machen kannst", "n.beta.required": "(Erforderlich) Ich stimme zu, dass meine E-Mail-Adresse zum Versand der Beta-Einladung erhoben und genutzt wird.", "n.beta.s1": "Anmeldung: Nötig ist nur deine E-Mail-Adresse. Ein Konto musst du nicht anlegen.", "n.beta.s2": "TestFlight-Einladung: Sobald die Beta öffnet, gehen die Einladungslinks in der Reihenfolge der Anmeldungen raus. Apple erlaubt bis zu 10.000 externe Tester. Du brauchst nur einen Apple Account und zahlst nichts. Im Beta-Build sind alle Coach-Funktionen kostenlos, solange die Beta läuft. Hast du das Häkchen bei den Neuigkeiten nicht gesetzt, bekommst du außer dieser Einladung keine Mail.", "n.beta.s3": "Feedback: direkt in der App oder per Mail an help@runvis.app.", "n.beta.s4": "Start: Der Termin wird nach der Beta festgelegt. Runvis erscheint zuerst im koreanischen App Store, andere Länder folgen nach und nach.", "n.beta.stepsh": "So geht es nach der Anmeldung weiter", "n.beta.sub": "Hinterlass deine E-Mail-Adresse, dann bekommst du eine Einladung, sobald die TestFlight-Beta öffnet. Steht der Termin fest, findest du ihn zuerst hier und bekommst ihn zusätzlich per Mail.", "n.beta.want": "Was möchtest du bekommen?", "n.beta.want1": "Bei der Beta mitmachen: Ich möchte die TestFlight-Einladung", "n.beta.want2": "Nur die Start-Info: einmal Bescheid, wenn die App da ist", "n.beta.do1": "<a href=\"run.html\">5-km-Demo</a>: Hör selbst, wann der Coach spricht, wann er still ist und wo die kostenlosen Ansagen aufhören und das Abo anfängt.", "n.beta.do2": "<a href=\"how-it-works.html#zones\">Pulszonen-Rechner</a>: Berechne deine 5 Pulszonen mit derselben Karvonen-Formel, die auch die Coach-Stimme nutzt. Du brauchst nur dein Alter und deinen Ruhepuls.", "n.beta.do3": "<a href=\"how-it-works.html#gpx\">13 Seouler Strecken als GPX</a>: Auch ohne die App jetzt herunterladen und auf deine Uhr oder in deine Karten-App laden.", "n.beta.do4": "<a href=\"how-it-works.html#beta\">Ablauf der Beta</a>: vier Schritte, von der Anmeldung über die TestFlight-Einladung und dein Feedback bis zum Start. Im Beta-Build sind alle Coach-Funktionen kostenlos, solange die Beta läuft.", "n.beta.do5": "<a href=\"privacy.html\">Datenschutzerklärung</a>: lückenlos aufgeschrieben, was dieses Formular erfasst und was die App überhaupt vom Gerät nach draußen schickt.", "n.faq.a1": "Ja. Auch nur mit dem iPhone zeichnest du per GPS auf und hörst nach jedem Kilometer (bei Meilen-Einstellung nach jeder Meile) dein Tempo für diesen Abschnitt. Ohne Abo bleibt es auf dem iPhone bei dieser einen Ansage. Mit Abo kommen auf dem iPhone Tempo-Hinweise dazu. Pulszonen-Ansagen gibt es nur mit einem verbundenen Bluetooth-Pulsgurt (einem Standard-BLE-Brustgurt wie Polar H10 oder Wahoo TICKR), denn das iPhone hat keinen Pulssensor. Technik-Coaching, Ansagen vor Anstiegen und die Warnung, wenn du von der Strecke abkommst, gibt es nur beim Laufen mit der Uhr.", "n.faq.a10": "Noch nicht. Komplikationen fürs Zifferblatt, ein Widget für den Home-Bildschirm des iPhone und Live-Aktivitäten sind in dieser Version nicht dabei. Geplant sind sie, einen Zeitpunkt gibt es noch nicht.", "n.faq.a2": "Du brauchst watchOS 10 oder neuer (Apple Watch Series 4 oder neuer) und iOS 17 oder neuer. Puls und GPS reichen. Neuere Modelle messen zusätzlich Bodenkontaktzeit und vertikale Bewegung, dort wird das Technik-Coaching feiner. Auf Modellen ohne diese beiden Werte coacht Runvis über die Schrittfrequenz.", "n.faq.a3": "Deine Läufe bleiben in der Health App. Auch nach der Kündigung kannst du weiter kostenlos aufzeichnen, Pläne ansehen und den Detailbericht zu jedem Lauf nutzen.", "n.faq.a4": "Es gibt kein Konto und keinen Server. Dein Standort verlässt das Gerät nur, wenn Runvis das Wetter, den Namen deines Stadtteils oder eine automatisch erstellte Strecke abruft. Dazu kommen die Zahlung über den App Store und der Download der öffentlichen Strecken- und Schuhlisten. Außerdem öffnet sich, vorerst nur im koreanischen App Store, eine externe Suchseite für Laufschuhe, und zwar nur, wenn du im Schuh-Bildschirm selbst darauf tippst. Trainings- und Gesundheitsdaten werden nicht hochgeladen.", "n.faq.a5": "Alles, was der iPhone-Coach sagt, wird in allen 6 Sprachen per Test geprüft. Bei jedem Build spielt ein Test einen 45-Minuten-Lauf Sekunde für Sekunde nach und prüft, ob jede Ansage übersetzt ist. Das Live-Coaching auf der Uhr deckt dieser Test noch nicht ab. Dort kann ein Satz noch unübersetzt sein, dann hörst du ihn auf Englisch. Auch dieser Wechsel ins Englische ist per Test abgesichert. Die Texte auf den App-Bildschirmen kommen aus einer eigenen Übersetzungstabelle, getrennt von der Coach-Stimme.", "n.faq.a6": "Ja. Ein 12-Minuten-Testlauf mit der Uhr genügt, und du bekommst noch am selben Tag deine geschätzte Zeit über 5 km und 10 km und deinen ersten Plan. Diesen Test gibt es nur auf der Uhr. Nur mit dem iPhone kannst du ab dem ersten Tag per GPS aufzeichnen, die Tempo-Ansage pro Abschnitt hören und deinen Trainingsplan ansehen. Der Plan startet dann bei deinen Wochenkilometern der letzten Zeit. Für die Laufbereitschaft müssen erst genug Nächte mit der Uhr am Handgelenk zusammenkommen, das dauert meist etwa 2 Wochen. Der ACWR braucht etwa 4 Wochen. „Effizienz vs. Basis“ erscheint, sobald du deinen Maximalpuls eingetragen hast und 3 Läufe über 10 Minuten mit Pulsaufzeichnung in derselben Intensität (locker, mittel oder hart) zusammenhast. Die ersten Male vergleicht Runvis noch mit einer Basis, die Intensität und Messzeitpunkt nicht trennt. Auch das steht dann auf dem Bildschirm.", "n.faq.a7": "Nur Accounts, bei denen der App Store feststellt, dass die Testphase für dieses Abo noch nicht genutzt wurde. Hattest du das Abo schon einmal oder die Testphase bereits genutzt, zahlst du ab der ersten Abrechnung. Welcher Fall bei dir gilt, zeigt dir der Kaufbildschirm der App immer vor dem Kauf. Die Testphase dauert beim Monats- und beim Jahresabo 1 Monat. Wählst du das Jahresabo, bekommst du also nicht 1 Jahr gratis: Nach 1 Monat wird der Jahrespreis auf einmal abgebucht. Die Dauer der Testphase liefert der App Store mit den Produktdaten, und die App zeigt sie dir direkt vor dem Kauf unverändert an.", "n.faq.a8": "Der lebenslange Zugang ist ein einmaliger Kauf ohne automatische Verlängerung. Gegenüber dem Jahresabo hat er sich nach etwa 2,6 Jahren bezahlt gemacht, gegenüber dem Monatsabo nach etwa 20 Monaten. Willst du Runvis länger nutzen, fährst du damit günstiger. Außerdem lässt sich nur „Lebenslang“ über die Familienfreigabe von Apple teilen, Monats- und Jahresabo nicht.", "n.faq.a9": "Deine Läufe liegen in der Health App, das neue Gerät übernimmt sie also automatisch. Was nur in Runvis gespeichert ist (Profil, Pulszonen, Schuhliste und die Basiswerte, die der Coach gesammelt hat), packst du unter Einstellungen → Daten → „Meine Daten exportieren“ in eine Datei. Auf dem neuen Gerät holst du alles mit „Aus Sicherung wiederherstellen“ zurück. Die Datei liegt nur dort, wo du sie speicherst. Runvis schickt sie nirgendwohin. Dein Abo bekommst du über „Käufe wiederherstellen“ im App Store zurück.", "n.faq.eb": "Häufige Fragen", "n.faq.h2": "Was du vor dem Start wissen willst", "n.faq.q1": "Geht es auch ohne Apple Watch?", "n.faq.q10": "Gibt es Komplikationen fürs Zifferblatt oder Widgets?", "n.faq.q2": "Welche Apple Watch brauche ich?", "n.faq.q3": "Was passiert mit meinen Läufen, wenn ich kündige?", "n.faq.q4": "Wohin gehen meine Daten?", "n.faq.q5": "Wie vollständig ist die Coach-Stimme in den 6 Sprachen?", "n.faq.q6": "Geht das auch ganz ohne bisherige Läufe?", "n.faq.q7": "Wer kann die Gratis-Testphase nutzen?", "n.faq.q8": "Lebenslang oder Jahresabo: Was lohnt sich mehr?", "n.faq.q9": "Was passiert, wenn ich das Gerät wechsle?", "n.hero.b1": "Deine Läufe verlassen das Gerät nicht", "n.hero.b1n": "Kein Konto, kein Server", "n.hero.b3": "entscheidet der Coach nach Schlaf und Puls", "n.hero.b3n": "Was du heute läufst", "n.hero.b5": "Aufzeichnen gratis · rund 1,30 € · Preise im Detail", "n.hero.b5n": "₩1,900 im Monat", "n.hero.cta1": "Für die Beta anmelden", "n.hero.cta2": "5-km-Demo laufen", "n.hero.eb": "Lauf-Coach für die Apple Watch", "n.hero.h1": "You run.<br/><span class=\"grad\">We coach.</span>", "n.hero.tag": "Already on your wrist.", "n.hero.note": "Du brauchst nur eine Apple Watch ab Series 4 und ein iPhone. Aufzeichnen ist kostenlos, nur der Coach ist ein Abo. Runvis startet zuerst im koreanischen App Store, andere Länder folgen nach und nach.", "n.hero.sub": "Laufen oder Pause? Wenn du morgens die App öffnest, steht es schon fest. Runvis wählt dein Training anhand der Schlaf- und Pulsdaten deiner Apple Watch. Und beim Laufen meldet sich der Coach per Stimme, aber nur dann, wenn es wirklich drauf ankommt.", "n.live.demo": "In der 5-km-Demo hören, wann der Coach spricht und wann er still ist", "n.live.eb": "Beim Laufen", "n.live.h2": "Nur was zählt.<br/>Genau dann, wenn es zählt.", "n.live.q.h": "Kein Dauergequatsche im Ohr", "n.live.q.moreh": "Alle Obergrenzen je Lauftyp und alle Ausnahmen ansehen", "n.live.q.n1": "Zwischen zwei Ansagen liegen mindestens 45 Sekunden. Sicherheitshinweise, wichtige Ansagen wie der Wechsel zum nächsten Trainingsschritt und die Splits kommen trotzdem sofort. Auch die folgenden Punkte sind ausgenommen.", "n.live.q.n2": "Splits, Ansagen vor Anstiegen und die Hinweise bei Auto-Pause und Weiterlaufen folgen eigenen Regeln und zählen deshalb nicht zur 30-Minuten-Obergrenze. Der Hinweis beim Wechsel zwischen Gehen und Laufen und das Atemzählen bringen nur etwas, wenn sie pünktlich kommen. Deshalb warten sie auch nicht die 45 Sekunden ab. Das gilt auch für die erste Begrüßung, wenn der Coach eine Strecke wiedererkennt, die du schon gelaufen bist.", "n.live.q.n3": "Läufst du nur mit dem iPhone, gelten andere Regeln. Es gibt weniger Ansagen, deshalb reichen 20 Sekunden Abstand. Tempo-Ansagen kommen höchstens alle 3 Minuten, Pulszonen-Ansagen höchstens alle 5 Minuten, und eine 30-Minuten-Obergrenze gibt es nicht.", "n.live.q.n4": "Du kannst 8 Arten von Ansagen einzeln ein- und ausschalten: Tempo, Pulszonen, Lauftechnik, Anstiege, Motivation & Skript, Lauf-Wissenskarte, Trinken & Verpflegung und die Ansage bei Pause & Fortsetzen. Bei den Splits wählst du statt eines Schalters den Abstand (aus, 0,5 oder 1, in km oder Meilen). Sicherheitshinweise und die Ansagen zu den Trainingsschritten lassen sich nicht abschalten. Deine Musik wird nur leiser, solange eine Ansage läuft.", "n.live.q.r1a": "Lockerer Lauf · langer Lauf · Lauf-Geh-Wechsel", "n.live.q.r1b": "bis zu 8", "n.live.q.r2a": "Tempolauf · Wettkampf · freier Lauf", "n.live.q.r2b": "bis zu 6", "n.live.q.r3a": "Intervalle", "n.live.q.r3b": "Keine Obergrenze. Dafür kommen bei Intervallen nur Ansagen zu Trainingsschritten, Pulszonen, Tempo und Auto-Pause. Splits, Anstiege, Technik und Motivation haben Pause", "n.live.q.th1": "Lauftyp", "n.live.q.th2": "Weitere Ansagen pro 30 Minuten (ohne Splits, Anstiege, Pausen)", "n.live.siri": "Sag „Hey Siri, Lauf starten mit Runvis“, und der Startbildschirm für deinen Lauf geht sofort auf. Das klappt in allen 6 Sprachen.", "n.live.sub": "Der Coach sagt nichts ohne Grund, und den Grund liefern die Sensoren. Tipp auf eine Ansage und hör sie dir an.", "n.nav.after": "Nach dem Lauf", "n.nav.cta": "Zur Beta", "n.nav.demo": "5-km-Demo", "n.nav.faq": "FAQ", "n.nav.live": "Beim Laufen", "n.nav.price": "Preise", "n.nav.race": "Wettkampf", "n.nav.today": "Heute", "n.nav.why": "Warum Runvis", "n.paths.c1h": "Ich laufe erst seit Kurzem", "n.paths.c1p": "Runvis klärt zuerst: Laufen oder Pause? Die Entscheidung für heute stützt sich auf Schlaf, HRV und deine Belastung von gestern.", "n.paths.c2h": "Ich laufe regelmäßig, aber ohne Coach", "n.paths.c2p": "Coaching per Stimme beim Laufen: Tempo, Anstiege, Technik.", "n.paths.c3h": "Ich bereite mich auf einen Wettkampf vor", "n.paths.c3p": "Zielzeitprognose und Tempostrategie pro Abschnitt, gerechnet bis hin zum Wetter am Wettkampftag.", "n.paths.c4h": "Ich will schneller werden", "n.paths.c4p": "Laktatschwelle, Intensitätsverteilung, Ausdauer-Trainingsumfang: Sieh dir an, was die Abo-Werte messen.", "n.paths.eb": "Wo fängst du an?", "n.paths.h2": "Wo stehst du gerade?", "n.paths.j1": "Erst mal der Preis", "n.paths.j2": "Erst mal: Wohin gehen meine Daten?", "n.paths.sub": "Wähl, was gerade zu dir passt. Du landest direkt bei der passenden Erklärung.", "n.pill.free": "Gratis", "n.pill.pro": "Abo", "n.price.cancel": "Kündigen kannst du jederzeit in den Einstellungen deines App-Store-Accounts. Den bezahlten Zeitraum nutzt du bis zum Ende, danach verlängert sich das Abo nicht mehr. Erstattungen richten sich nach den Richtlinien von Apple.", "n.price.cta": "Erst in der Beta ausprobieren oder nur zum Start benachrichtigt werden", "n.price.eb": "Preise", "n.price.f1": "GPS-Aufzeichnung, Tempo, Puls, Runden, Speichern in der Health App", "n.price.f2": "Detailbericht zum Lauf, Körperbericht, Liste deiner Läufe", "n.price.f3": "Trainingspläne ansehen, einfache Rennzeitprognose, Wetter-Briefing und Aufwärm-Bildschirm, Wettkampfmodus auf der Uhr mit deiner Bestzeit als Ghost", "n.price.f4": "Sprachansagen beim Laufen mit der Uhr: Splits (in der Einheit deines Geräts), Pulszonen, Tempo, Ansage vor Anstiegen, Warnung bei Streckenabweichung", "n.price.f4b": "Mit dem iPhone allein gibt es gratis nur die Splits", "n.price.f5": "GPX-Export, Bericht zur KI-Analyse", "n.price.freeName": "Basis", "n.price.freecta": "In der 5-km-Demo testen, wie weit du gratis kommst", "n.price.gateh": "Wann erscheinen die Werte?", "n.price.gatelead": "Die 8 Kacheln sind ab dem Kauf freigeschaltet. Die Zahlen füllen sich, je mehr Läufe zusammenkommen. Bis dahin zeigt jede Kachel, was ihr noch fehlt.", "n.price.g1": "Laktatschwelle (geschätzt): 2 Abschnitte von 30 (oder 20) Minuten mit mindestens 85 % des Maximalpulses. Hast du nur Läufe ohne Route, reichen ein eingetragener Maximalpuls und 3 Läufe von mindestens 20 Minuten.", "n.price.g2": "Ausdauer-Trainingsumfang: mindestens 6 Läufe, verteilt auf 3 der letzten 4 Wochen (zwischen erstem und letztem Lauf mindestens 2 Wochen).", "n.price.g3": "Hügelanteil: 2 Läufe mit Anstieg.", "n.price.g4": "Hitzebelastungsindex: 3 Läufe an Tagen über 22 °C.", "n.price.g5": "Intensitätsverteilung: Daten aus 8 Tagen, darunter 5 Läufe mit Pulsaufzeichnung.", "n.price.g6": "Coach-Bremse: 2 Wochen mit Laufdaten.", "n.price.g7": "Rekord-Radar des Coachs: Schon ein Lauf ab 1 km reicht, damit die ersten Bestzeiten erscheinen.", "n.price.g8": "Beinbelastung: Einen Wert gibt es schon ab 1 Lauf mit aufgezeichneter Distanz.", "n.price.h2": "Aufzeichnen ist gratis,<br/>der Coach kostet ₩1,900 im Monat", "n.price.life": "Statt Abo: <b>lebenslanger Zugang für ₩39,000</b>. Das ist ein Einführungspreis. Steigt er später, betrifft das niemanden, der schon gekauft hat. Mit den Preisen im koreanischen App Store hat er sich gegenüber dem Jahresabo (₩15,000) nach etwa 2,6 Jahren bezahlt gemacht, gegenüber dem Monatsabo (₩1,900) nach etwa 20 Monaten. Nur „Lebenslang“ lässt sich über die Familienfreigabe von Apple teilen.", "n.price.p1": "Coach-Stimme beim Laufen: Technik, richtig am Berg laufen, Erholung, Motivation", "n.price.p2": "Plan laufen: Der Coach führt dich durch jeden Abschnitt, am Ende gibt es die Bewertung gegen den Plan", "n.price.p3": "Im Bericht werden 8 Kacheln mit Tiefenanalyse freigeschaltet", "n.price.p4": "Wettkampfstrategie: Tempoplan pro Abschnitt, Verpflegungsplan, Generalprobe", "n.price.p5": "Wochenkarte „Diese Woche mit dem Coach“: Bewertung gegen den Plan, dein schnellster Abschnitt der Woche, restliches Kilometerbudget, Intensitätsverteilung der letzten 4 Wochen und eine Sache, die du nächste Woche ändern kannst. Gratis siehst du sie als gesperrte Vorschau.", "n.price.p6": "Der Runvis-Fitnessindex aus deinen Bestleistungen prognostiziert deine Zeiten von 5 km bis Marathon", "n.price.t1": "Laktatschwelle (geschätzt)", "n.price.t2": "Ausdauer-Trainingsumfang", "n.price.t3": "Hügelanteil", "n.price.t4": "Hitzebelastungsindex", "n.price.t5": "Coach-Bremse", "n.price.t6": "Intensitätsverteilung", "n.price.t7": "Rekord-Radar des Coachs (schnellste Abschnitte, letzte 90 Tage)", "n.price.t8": "Beinbelastung", "n.price.sub": "Aufzeichnen, Pläne ansehen und Berichte sind gratis. Im Abo steckt alles, bei dem der Coach selbst spricht und auswertet. Stuft der App Store deinen Account als berechtigt ein, kannst du 1 Monat gratis testen. Das gilt beim Monats- wie beim Jahresabo.", "n.price.year": "Jährlich <b>₩15,000</b>. Im koreanischen App Store sind das rund ₩1,250 im Monat, etwa 34 % günstiger als monatlich. In anderen Ländern gelten andere Preisstufen, das Verhältnis kann dort also anders ausfallen. Die tatsächliche Ersparnis rechnet dir der Kaufbildschirm der App mit den Preisen deines Landes aus. Bei berechtigten Accounts gibt es auch beim Jahresabo eine Testphase, aber wie beim Monatsabo 1 Monat, nicht 1 Jahr. Nach 1 Monat werden die ₩15,000 für das ganze Jahr auf einmal abgebucht.", "n.priv.big": "Kein Konto, kein Server.<br/>Der Coach spricht sogar im Tunnel.", "n.priv.eb": "Datenschutz", "n.priv.link": "Datenschutzerklärung", "n.priv.p": "Aufzeichnung und Analyse laufen komplett auf Apple Watch und iPhone. Nach draußen geht nur Folgendes: fürs Wetter deine Koordinaten, auf etwa 1 km gerundet; für den Namen deines Stadtteils und automatisch erstellte Strecken deine aktuellen Koordinaten an Apple-Dienste, nur in diesem Moment; die Zahlung über den App Store; der Download der öffentlichen Strecken- und Schuhlisten. Außerdem öffnet sich, vorerst nur im koreanischen App Store, eine externe Suchseite für Laufschuhe, und zwar nur, wenn du auf Apple Watch oder iPhone im Schuh-Bildschirm selbst darauf tippst. Jede dieser Ausnahmen steht lückenlos in der Datenschutzerklärung. Trainings- und Gesundheitsdaten werden nirgendwohin hochgeladen.", "n.race.eb": "Wettkampfvorbereitung", "n.race.h2": "Woche für Woche zum Wettkampf,<br/>am Wettkampftag Abschnitt für Abschnitt", "n.race.h3": "Wähl deinen Coach, Plan und Tonfall passen sich an", "n.race.h3b": "Ein Coach, der die Wettkampfstrecke schon kennt", "n.race.l1": "Bei Intervallen führt dich der Coach durch jeden Abschnitt und bewertet am Ende, wie nah du am Plan warst", "n.race.l2": "Schlechter Tag? Ein Tipp senkt die Intensität, und der Plan wird neu aufgestellt", "n.race.l3": "Noch keine Zeiten? Kein Problem. Ein 12-Minuten-Testlauf mit der Uhr, und dein erster Plan steht", "n.race.lb1": "Aus einer aktuellen Zeit: Prognose und Zieltempo für 5 km, 10 km, Halbmarathon und Marathon", "n.race.lb2": "Läufst du dieselbe Strecke noch mal, läuft deine Bestzeit als Ghost mit und zeigt dir, wie weit du vorn oder hinten liegst", "n.race.lb3": "Ab 16 Tagen vor dem Wettkampf fließt die Wettervorhersage für den Wettkampftag in die Prognose ein", "n.race.p": "„Sicher ankommen“, „Ausgewogen“ oder „Auf Bestzeit“: Je nachdem, welchen Coach du wählst, ändern sich Trainingsaufbau und Tonfall beim Laufen. Wer gerade erst anfängt, bekommt bei keinem Coach überzogene Intervalle.", "n.race.pb": "Lädst du die GPX der Wettkampfstrecke, weiß Runvis vorher, wo die Anstiege beginnen. Schickst du das Tempo pro Abschnitt (Steigung eingerechnet) und die Verpflegungszeitpunkte vorab auf die Uhr, folgst du am Wettkampftag einfach den Ansagen.", "n.race.sub": "Gib deinen Zielwettkampf und deine Zielzeit ein, und du bekommst einen Fahrplan bis zum Wettkampftag, Woche für Woche. Ob das Ziel zu deiner aktuellen Form passt, sagt dir Runvis ehrlich. Den Plan ansehen ist gratis. Dass dich der Coach auf der Uhr durch jeden Abschnitt führt, gehört zum Abo.", "n.st.caution": "Achtung", "n.st.fair": "Mittel", "n.st.good": "Gut", "n.step1h": "Wetter-Briefing", "n.step1p": "Mit dem aktuellen Wetter genau da, wo du gerade bist.", "n.step1q": "„Aktuell sind es 26 Grad bei 78 Prozent Luftfeuchtigkeit. Heiß und schwül — die Verdunstung arbeitet gegen dich.“", "n.step2h": "Aufwärmen", "n.step2p": "Ein Timer führt dich durch jeden Schritt. Mit Coach zählt eine Stimme mit.", "n.step2q": "„Armkreisen, 30 Sekunden. Jetzt rückwärts. Drei, zwei, eins.“", "n.step3h": "Einfach loslaufen", "n.step3p": "Sobald die Uhr deinen Laufrhythmus erkennt, startet die Aufzeichnung von selbst.", "n.step3q": "„Du läufst los. Ich starte die Aufzeichnung.“", "n.steps.h": "Einmal Start drücken reicht", "n.steps.note": "Bildschirm, Timer und Autostart sind gratis. Die Stimme des Coachs, die dich durchführt, gehört zum Abo.", "n.today.eb": "Entscheidung heute", "n.today.h2": "Morgens reinschauen.<br/>Dein Training steht schon fest.", "n.today.h3": "Oben die Entscheidung, direkt darunter die Gründe", "n.today.l1": "An schwächeren Tagen senkt Runvis die Intensität und sagt dir, warum", "n.today.l2": "Willst du trotzdem wie geplant laufen, kannst du das", "n.today.l3": "Reichen die Daten nicht, steht dort „Lernt noch“ statt einer Zahl", "n.today.m1": "Schlaf", "n.today.m3": "Belastung gestern", "n.today.p": "Ganz oben steht dein Training für heute, darunter die Gründe dafür. Alle anderen Werte findest du zum Nachschlagen weiter unten. Tippst du eine Zahl an, siehst du, was sie bedeutet, wie sie berechnet wird und was bei dir normal ist.", "n.today.siri": "Du musst nicht mal auf die Uhr schauen. Sag „Hey Siri, was laufe ich heute mit Runvis“, und du hörst die Entscheidung für heute. Laufbereitschaft und Wochenplan fragst du genauso ab.", "n.today.sub": "Runvis vergleicht deinen Schlaf der letzten Nacht, HRV, Ruhepuls und die Trainingslast von gestern mit deinem üblichen Bereich der letzten 28 Tage. Daraus wählt es dein Training für heute und sagt dir in einem Satz, warum.", "n.today.w1": "Entscheidung heute", "n.today.w1p": "Ring der Laufbereitschaft und dein Training für heute, direkt am Handgelenk.", "n.today.w2": "Grundlage heute", "n.today.w2p": "Schlaf, HRV und Belastung von gestern im Vergleich zu deinem üblichen Bereich, angezeigt als Gut, Mittel oder Achtung.", "n.today.w3": "Start mit einem Tipp", "n.today.w3p": "Dein Training für heute steht ganz oben auf dem Startbildschirm. Tipp drauf, und der Coach führt dich durch jeden Abschnitt.", "n.trust.h": "Was du jetzt schon nachprüfen kannst", "n.trust.l1": "827 automatische Tests prüfen bei jedem Build die Sätze des Coachs, die Grenze zwischen gratis und Abo und die Planberechnung.", "n.trust.l2": "2.366 Bildschirmtexte gibt es lückenlos in allen 6 Sprachen. Die 4 Übersetzungstabellen der Coach-Stimme haben jeweils genau 396 Einträge. Passt irgendwo etwas nicht, schlägt der Test sofort fehl.", "n.trust.l3": "In der App stecken 42 Erklärungen zu den Werten. Tippst du auf eine Zahl, die du nicht kennst, siehst du, was sie bedeutet, wie sie berechnet wird und was bei dir normal ist.", "n.trust.p": "Runvis baue ich allein. Die App ist noch nicht erschienen, es gibt also weder Bewertungen noch Presse. Statt schöner Zahlen stehen hier nur Fakten, die man direkt im Code der App nachzählen kann. Fragen? Schick sie an help@runvis.app. Die Antwort schreibe ich selbst.", "n.vc1.aria": "Beispielansage abspielen: Tempo (gratis)", "n.vc1.line": "\"25 Sekunden schneller als das Ziel\"", "n.vc1.play": "Tempo", "n.vc1.sensor": "📡 Wenn du länger als 20 Sekunden um mindestens 20 Sekunden von deinem Zieltempo abweichst", "n.vc2.aria": "Beispielansage abspielen: Anstieg voraus (gratis)", "n.vc2.line": "\"In 300 Meter beginnt ein Anstieg über 800 Meter. Durchschnittlich 4 Prozent. Verkürze den Schritt und halte den Rhythmus.\"", "n.vc2.play": "Anstieg voraus", "n.vc2.sensor": "📡 Liest das Höhenprofil der Strecke im Voraus. Auf Strecken, die du oft läufst, erkennt Runvis den Weg nach etwa 500 m und kündigt die Anstiege an", "n.vc3.aria": "Beispielansage abspielen: Schrittlänge (Abo)", "n.vc3.line": "\"Die Schrittfrequenz liegt 5 Prozent unter deiner Basis – verkürzen wir den Schritt ein wenig?\"", "n.vc3.play": "Schrittlänge", "n.vc3.sensor": "📡 Schrittlängen-Hinweis · nur auf flacher Strecke bei gleichmäßigem Tempo. Er kommt, wenn deine Schrittfrequenz zwischen 130 und 160 Schritten pro Minute liegt und 30 Sekunden lang 5 % unter deinem Normalwert bleibt. Bodenkontaktzeit über 300 ms oder eine größere vertikale Bewegung lösen denselben Hinweis aus (unabhängig vom Frequenzbereich). Frühestens 6 Minuten nach dem Start, höchstens 2-mal pro Lauf. Der Schalter „Lauftechnik“ in den Einstellungen schaltet diesen Hinweis und den Technik-Hinweis gemeinsam ein und aus.", "n.vc4.aria": "Beispielansage abspielen: Erholung (Abo)", "n.vc4.line": "\"Dein Puls ist bis auf Zone 3 gefallen. Du erholst dich gut — fast geschafft.\"", "n.vc4.play": "Erholung", "n.vc4.sensor": "📡 Wenn dein Puls in der Gehpause um eine Zone sinkt, zum Beispiel auf Zone 3", "n.why.c1h": "Die Sensoren sind schon am Handgelenk", "n.why.c1p": "Puls, GPS, Schrittfrequenz, Höhe. Neuere Modelle messen sogar Bodenkontaktzeit und vertikale Bewegung.", "n.why.c2h": "Die Formeln sind öffentlich", "n.why.c2p": "Trainingslast, Erholungszeit und Schwellenschätzung beruhen auf veröffentlichten Formeln, die in der Sportwissenschaft weit verbreitet sind. Runvis rechnet sie direkt auf Apple Watch und iPhone.", "n.why.c3h": "Gefehlt hat nur der Coach", "n.why.c3p": "Jemand, der die Zahlen liest, dein Training für heute festlegt und beim Laufen an deiner Seite mit dir spricht. Genau diese Rolle übernimmt Runvis.", "n.why.eb": "Warum Runvis", "n.why.h2": "Du brauchst keine<br/>zweite Laufuhr", "n.why.phone": "Noch keine Apple Watch? Du kannst trotzdem starten. Auch nur mit dem iPhone wird dein Lauf per GPS aufgezeichnet, und du hörst nach jedem Kilometer (bei Meilen-Einstellung nach jeder Meile) dein Tempo für diesen Abschnitt. Ohne Abo bleibt es auf dem iPhone bei dieser einen Ansage. Technik-Coaching braucht die Sensoren am Handgelenk und gibt es deshalb nur mit der Uhr.", "n.why.s1": "Werte mit Erklärung zum Antippen", "n.why.s1n": "direkt in der App", "n.why.s1v": "42", "n.why.s2": "Sätze vom Coach", "n.why.s2n": "in 6 Sprachen", "n.why.s2v": "287", "n.why.s3": "Automatische Tests", "n.why.s3n": "bei jedem Build", "n.why.s3v": "827", "n.why.sub": "Für Trainingslast oder Erholungszeit brauchst du angeblich eine eigene Laufuhr, etwa von Garmin oder Coros. Dabei steckt jeder Sensor, den diese Rechnung braucht, schon in der Apple Watch an deinem Handgelenk.", "nf.title": "Seite nicht gefunden – Runvis", "nf.h1": "Unter dieser Adresse gibt es keine Seite", "nf.p": "Vielleicht hat sich der Link geändert, oder die Adresse wurde falsch eingegeben. Wähl unten einfach, wohin du möchtest.", "nf.l1": "Zur Startseite", "nf.l2": "5-km-Demo laufen", "nf.l3": "Rechenwege und Tools", "ph.email": "E-Mail-Adresse", "pl.coach": "Runvis Coach", "pl.ribbon": "1 Monat gratis für berechtigte Accounts", "pl.terms": "Wer bekommt die Testphase?", "pr.approx": "Das sind die Preise im koreanischen App Store. In anderen Ländern gilt der Preis in Landeswährung, den der dortige App Store festlegt.", "pr.approxref": "Du liest das außerhalb Koreas? Dann nimm diese Werte nur als grobe Orientierung: ₩1,900 im Monat sind rund 1,30 €, ₩15,000 im Jahr rund 10 € und der lebenslange Zugang für ₩39,000 rund 26 €. Das ist nur eine Umrechnung, nicht der Betrag, den du zahlst.", "pr.free": "Kostenlos", "pr.launch": "Runvis erscheint zuerst im koreanischen App Store, andere Länder folgen nach und nach. Der Starttermin wird nach der TestFlight-Beta festgelegt, und du erfährst ihn zuerst auf dieser Seite.", "pr.month": "₩1,900", "pv.back": "← Zurück zu Runvis", "pv.h1": "Datenschutzerklärung", "pv.legalNote": "Die koreanische Fassung ist die rechtsverbindliche Version. Andere Sprachen sind Übersetzungen zum besseren Verständnis; bei Auslegungsunterschieden gilt die koreanische Fassung. Kontakt: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.meta.desc": "Runvis verarbeitet Lauf- und Gesundheitsdaten ausschließlich auf deinem Gerät. Kein Server, kein Konto — und jede Ausnahme, die das Gerät verlässt, steht hier.", "pv.meta.title": "Datenschutzerklärung — Runvis", "pv.s1.h": "1. Erhobene und verarbeitete Daten", "pv.s1.li1": "<b>Trainingsdaten</b>: Herzfrequenz, Pace, Distanz, GPS-Route, Höhe, Schrittfrequenz, Laufleistung, Schrittlänge, Bodenkontaktzeit und Vertikalbewegung (auf unterstützten Geräten), Kalorien — über Apple HealthKit gelesen und gespeichert", "pv.s1.li2": "<b>Gesundheitsdaten</b>: Schlaf (Dauer und Phasen), Herzfrequenzvariabilität (HRV), Ruhepuls, VO₂max und, falls gewünscht, Menstruationszyklus — für Laufbereitschaft und Erholungsanalyse", "pv.s1.li3": "<b>Bewegungsdaten</b>: Handgelenkbeschleunigung (zur automatischen Erkennung des Laufstarts) und, sofern getragen, Kopfbewegung der AirPods — als unterstützendes Techniksignal", "pv.s1.li4": "<b>Profilangaben</b>: Geburtsjahr, Geschlecht, Ruhepuls und maximale Herzfrequenz — von dir im ersten Einrichtungsbildschirm eingegeben und ausschließlich als Grundlage für Herzfrequenzzonen und altersbasierte Schätzungen verwendet", "pv.s1.li5": "<b>Weitere Eingaben</b>: Zielwettkampf und Zielzeit, Coach-Tonfall, Schuhdaten und der Check-in nach dem Lauf (Belastung, Schmerzen, Flüssigkeit)", "pv.s1.li6": "<b>Bluetooth-Sensoren</b>: sofern verbunden, Live-Werte von Herzfrequenzgurt, Fahrrad-Powermeter oder Smart-Trainer", "pv.s1.li7": "<b>Diagnosedaten</b>: Absturz- und Hänger-Berichte (Apple MetricKit) — nur auf dem Gerät gespeichert; sie verlassen es ausschließlich, wenn du sie selbst exportierst oder teilst", "pv.s1.p": "Runvis liest und verarbeitet die folgenden Daten <b>auf dem Gerät</b>. Alle dienen der App-Funktion und verlassen das Gerät nicht.", "pv.s10.h": "10. Änderungen und Kontakt", "pv.s10.p": "Bei Änderungen dieser Erklärung wird das Datum auf dieser Seite aktualisiert. Die Nutzungsbedingungen findest du unter <a href=\"terms.html\">Nutzungsbedingungen</a>. Kontakt: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s2.h": "2. Wo die Daten gespeichert werden", "pv.s2.li1": "Trainings und Routen werden in <b>Apple Health (HealthKit)</b> gespeichert — sie gehören dir, und ob sie über iCloud Health synchronisiert werden, richtet sich nach deinen iOS-Einstellungen", "pv.s2.li2": "App-Einstellungen, Profilangaben, Pläne, Strecken und Abzeichen-Berechnungen liegen <b>ausschließlich im gerätelokalen Speicher der App</b>", "pv.s2.li3": "Runvis betreibt keinen eigenen Server, keine Datenbank und kein Kontosystem", "pv.s2.li4": "Runvis führt kein eigenes Backup und keine eigene Synchronisierung durch. Beim Gerätewechsel wandern die in Apple Health gespeicherten Workouts mit, die nur im App-Speicher liegenden Werte — Profil, Schuhe, Plan, Abzeichen und die vom Coach gebildeten Basislinien — dagegen nicht. Über Einstellungen → Daten schreibt „Meine Daten exportieren“ diese Werte in eine einzige Datei, die „Aus Backup importieren“ auf dem neuen Gerät zurückholt; diese Datei bleibt nur dort, wo du sie speicherst, und Runvis schickt sie nirgendwohin", "pv.s3.h": "3. Alles, was das Gerät verlässt (vollständige Liste)", "pv.s3.note": "Keiner der oben genannten Fälle enthält identifizierende Angaben wie Name oder E-Mail-Adresse, und Runvis führt darüber kein separates Protokoll. Runvis <b>lädt</b> die erfassten Trainings- und Gesundheitsdaten <b>nicht hoch</b> — die App enthält dafür keinen Code, und alle oben genannten Verbindungen sind reine Leseanfragen mit dem Minimum an nötigen Informationen.", "pv.s3.r1a": "Wetter-Briefing", "pv.s3.r1b": "Auf etwa 1 km gerundete Koordinaten (Genauigkeit auf Stadtteilebene) und die Uhrzeit — nur im Moment der Anfrage, ohne Speicherung und ohne Kennung", "pv.s3.r1c": "Open-Meteo (kostenlose Wetter-API)", "pv.s3.r2a": "Abo-Zahlung", "pv.s3.r2b": "Der gesamte Zahlungsvorgang — Runvis kann Karten- oder Zahlungsdaten weder sehen noch speichern", "pv.s3.r2c": "Apple App Store", "pv.s3.r3a": "Automatische Streckenerstellung", "pv.s3.r3b": "Deine aktuellen Koordinaten für die Routenberechnung — nur im Moment der Anfrage und ungerundet", "pv.s3.r3c": "Apple Karten (MapKit)", "pv.s3.r4a": "Anzeige des Ortsnamens", "pv.s3.r4b": "Deine aktuellen Koordinaten, damit Wetter-Briefing und Trainingsaufzeichnung einen Ortsnamen tragen können — nur im Moment der Abfrage und ungerundet. Das Ergebnis wird auf dem Gerät zwischengespeichert, derselbe Ort wird also kein zweites Mal abgefragt", "pv.s3.r4c": "Apple Ortungsdienste (CLGeocoder)", "pv.s3.r5a": "Download des Strecken- und Schuhkatalogs", "pv.s3.r5b": "<b>Es wird nichts gesendet</b> — einmal täglich wird anonym eine öffentliche Datei heruntergeladen (wie bei jedem Website-Besuch ist deine IP-Adresse für den Host sichtbar)", "pv.s3.r5c": "GitHub Pages (Hosting statischer Dateien)", "pv.s3.r6a": "Laufschuh-Suche öffnen", "pv.s3.r6b": "<b>Es wird nichts gesendet</b> — nur wenn du auf dem Schuh-Bildschirm der Uhr oder des iPhones selbst tippst, öffnet sich ein externer Browser mit einer Adresse, die den Suchbegriff „Laufschuhe“ enthält. Trainings-, Gesundheits- oder Schuhdaten gehen dabei nicht mit", "pv.s3.r6c": "Ein externer Shop — derzeit die Suchseite des koreanischen Händlers Coupang", "pv.s3.th1": "Ausnahme", "pv.s3.th2": "Was gesendet wird", "pv.s3.th3": "Empfänger", "pv.s4.h": "4. Wofür die Berechtigungen genutzt werden", "pv.s4.li1": "<b>Health (HealthKit)</b>: Trainings speichern und frühere Aufzeichnungen auswerten", "pv.s4.li2": "<b>Standort</b>: Aufzeichnung der Laufstrecke, Wetter-Briefing und Streckenführung", "pv.s4.li3": "<b>Bewegung</b>: automatische Erkennung des Laufstarts und Anleitung beim Aufwärmen", "pv.s4.li4": "<b>Mitteilungen</b> (optional, 9 Arten): Erinnerungen an Plantage, das Abendbriefing, die sonntägliche Wochenzusammenfassung des Coachs, ein Anstupser nach längerer Pause, ein Hinweis in der ersten Woche nach dem Abschluss, ein Hinweis zwei Tage bevor die Gratis-Testphase oder der Coach-Modus endet, eine Einladung zum Wiederabonnieren eine Woche nach der Kündigung (das ist Werbung), die Mitteilung der Uhr über abgeschlossene Erholung und der Ruhe-Anstupser der Uhr — der Text entsteht auf dem Gerät und wird nie an einen Server gesendet", "pv.s4.li5": "<b>Bluetooth</b>: Verbinden externer Sensoren (Herzfrequenzgurte, Powermeter)", "pv.s4.li6": "<b>Kalender</b> (optional): Trainingseinheiten in den Kalender eintragen", "pv.s4.li7": "<b>Fotos</b> (optional): Speichern des Routen-Flyover-Videos", "pv.s4.note": "Du kannst jede Berechtigung ablehnen; betroffen ist nur die jeweilige Funktion, der Rest der App funktioniert weiter.", "pv.s5.h": "5. Dritte, Werbung und Tracking", "pv.s5.li1": "Weitergabe an Dritte: <b>keine</b> — bezogen auf die Trainings- und Gesundheitsdaten, die die App verarbeitet. Die einzige Ausnahme ist die Beta-Anmelde-E-Mail auf der Website, die im Auftrag von Formspree verarbeitet und in Abschnitt 6 beschrieben wird", "pv.s5.li2": "Werbe-SDKs, Analyse-SDKs und Tracking-Tools: <b>keine</b>", "pv.s5.li3": "Verkauf von Daten: <b>keiner</b>", "pv.s6.h": "6. Die Website (Beta-Anmeldung)", "pv.s6.li1": "<b>Was erhoben wird</b>: die E-Mail-Adresse, und zwar nur die von dir selbst eingegebene", "pv.s6.li2": "<b>Zweck</b>: Versand der TestFlight-Beta-Einladung und Hinweise zur Beta", "pv.s6.li3": "<b>Auftragsverarbeitung und Drittlandtransfer</b>: Übermittlung und Speicherung des Formulars übernimmt <b>Formspree, Inc.</b> (USA), sodass die eingereichte Adresse an Formspree-Server in den Vereinigten Staaten übertragen und dort gespeichert wird — <a href=\"https://formspree.io/legal/privacy-policy/\" rel=\"noopener\">Datenschutzerklärung von Formspree</a>", "pv.s6.li4": "<b>Speicherung und Löschung</b>: Die Adresse wird unverzüglich gelöscht, sobald der Zweck erfüllt ist (Beta-Einladung versendet), spätestens jedoch ein Jahr nach der Erhebung. Löschanfragen: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s6.p": "Wenn du über das Beta-Anmeldeformular auf runvis.app eine E-Mail-Adresse übermittelst, wird sie wie folgt verarbeitet. Dieser Abschnitt gilt nur für das Website-Formular; die App erhebt keinerlei Kontodaten, auch keine E-Mail-Adresse.", "pv.s7.h": "7. Löschen der Daten", "pv.s7.p": "Wenn du die App löschst, wird alles in ihrem Speicher gelöscht, einschließlich der Profilangaben. In HealthKit gespeicherte Trainings gehören dir und bleiben auch nach der Deinstallation in der Health-App; dort kannst du sie selbst löschen.", "pv.s8.h": "8. Kinder", "pv.s8.p": "Runvis richtet sich nicht an Kinder unter 14 Jahren. Der erste Einrichtungsbildschirm fragt das Geburtsjahr ab, um Herzfrequenzzonen und altersbasierte Schätzungen zu berechnen; dieser Wert wird ausschließlich auf dem Gerät gespeichert und nie übertragen. Nutzt ein Kind die App über die Familienfreigabe des lebenslangen Zugangs, ist die Begleitung durch Erziehungsberechtigte erforderlich.", "pv.s9.h": "9. Medizinischer Haftungsausschluss", "pv.s9.p": "Alle Zahlen und Hinweise in Runvis sind <b>Schätzwerte zur Orientierung</b> auf Basis veröffentlichter sportwissenschaftlicher Formeln und stellen keine medizinische Diagnose, Behandlung oder Verordnung dar. Bei Symptomen wie Brustschmerz oder Schwindel brich das Training sofort ab und wende dich an Fachpersonal.", "pv.summary": "<b>In einem Absatz</b> — Runvis verarbeitet deine Lauf- und Gesundheitsdaten <b>ausschließlich auf deinem Gerät</b>. Es gibt keinen Runvis-Server und kein Konto, und deine Trainings- und Gesundheitsdaten werden niemals übertragen, verkauft oder geteilt — auch nicht mit dem Entwickler. Alle Ausnahmen (Wetterabruf, Apple-Zahlungen, Routenberechnung auf der Karte, Abruf des Ortsnamens, Download der öffentlichen Strecken- und Schuhlisten sowie der Laufschuh-Suchlink, den du selbst antippst) sind unten vollständig aufgeführt.", "pv.updated": "Gültig ab: 2. Oktober 2026 · Version 1.4", "r.alt.elev": "Höhenprofil der nächsten 1,5 Kilometer: In 300 Metern beginnt der Anstieg, insgesamt 34 Höhenmeter", "r.alt.watch": "Bildschirm der Apple Watch: Tagesziel 5,0 Kilometer, „Mit Runvis laufen“", "r.badge.note": "Jede Coach-Ansage ist mit <span class=\"pill free\">Gratis</span> oder <span class=\"pill pro\">Abo</span> markiert. Aufzeichnen, Runden, Speichern in der Health App, deine Läufe ansehen, Trainingspläne ansehen, der Detailbericht zum Lauf und der Aufwärm-Bildschirm sind alle gratis.", "r.hud.dist": "DIST", "r.hud.hr": "HF", "r.hud.pace": "TEMPO", "r.hud.zone": "ZONE", "r.rail.aria": "Zu Abschnitten des Laufs springen", "r.signup.h": "Die 5 km hast du geschafft", "r.signup.p": "Du willst die Ansagen, die du gerade gelesen hast, am eigenen Handgelenk hören? Dann trag dich gleich hier ein. Steht der Starttermin fest, erfährst du ihn zuerst per Mail an diese Adresse. Die Einladungen gehen in der Reihenfolge der Anmeldungen raus.", "r.signup.price": "Preise ansehen", "r.tier.free": "GPS-Aufzeichnung, Runden, Speichern in der Health App, alle Läufe ansehen · Trainingspläne ansehen · Detailbericht zum Lauf · Aufwärm-Bildschirm · mit der Uhr: Ansagen für Splits pro km (oder Meile), Pulszonen, Tempo, Anstiege auf der Strecke und Streckenabweichung (mit dem iPhone allein gibt es gratis nur die Splits) · Tipp-Karte nach dem Lauf · Wettkampfmodus mit Ghost-Anzeige", "r.tier.price": "Wähl zwischen ₩1,900 im Monat, Jahresabo und lebenslangem Zugang. Es gelten die Preise im App Store. Kein Konto, kein Server: Deine Daten bleiben nur auf dem Gerät und in der Health App.", "r.tier.pro": "Technik-Coaching per Stimme, dazu Ansagen fürs Laufen am Berg, zur Erholung und zur Motivation · Trainingsplan Abschnitt für Abschnitt laufen, am Ende die Bewertung gegen den Plan · 8 Kacheln mit Tiefenanalyse · Wettkampfstrategie (Generalprobe, Tempoplan pro Abschnitt, Verpflegungsplan) · Wochenkarte „Diese Woche mit dem Coach“", "r.unitnote": "Diese Demo läuft nur in Kilometern. Die App folgt der Einheit deines Geräts: Splits nach jedem Kilometer oder jeder Meile, und auch Distanz und Tempo auf dem Display und in den Ansagen kommen in dieser Einheit.", "r.silence": "Nächste Ansage in {km} km · auf diesem Abschnitt sagt der Coach nur die 1-km-Splits an", "r.warmup.v": "7 SCHRITTE", "r1": "RUN SESSION — 5 km mit Runvis | Runvis", "r10": "RUNVIS // LIVE COACHING DEMO", "r11": "Heute läufst du<br><span class=\"outline\">mit Coach</span>.", "r12": "Ab hier gilt: <b>Scrollen ist Laufen</b>. Scroll nach unten, und dein 5-km-Lauf beginnt. Distanz, Tempo und Puls unten auf dem Bildschirm laufen mit. Erlebe selbst, <b>wann und warum Runvis coacht</b> und wann es still bleibt.", "r13": "Die Zahlen hier sind Beispiele für die Demo · die echte App arbeitet mit den Sensoren der Apple Watch", "r14": "Kilometer · Ziel für heute", "r15": "Mit Runvis laufen", "r16": "Briefing · Aufwärmen · Coaching", "r17": "SEGMENT 00 — VOR DER HAUSTÜR · 05:52 AM", "r18": "Bevor du losläufst,<br><span class=\"grad\">kümmert sich der Coach um dich</span>", "r19": "Einmal Start drücken, und es geht direkt weiter: <b>Wetter-Briefing → Aufwärmen</b>. Ohne eigenen Server, direkt auf der Uhr.", "r2": "Scrollen ist Laufen. Vom Aufwärmen bis ins Ziel: Lauf die 5 km mit und hör selbst, wann und warum sich der Coach von Runvis meldet.", "r20": "„Hallo, hier ist Runvis. Laufen wir heute zusammen? Das ist das aktuelle Wetter in Yeouido-dong. Aktuell sind es 26 Grad bei 78 Prozent Luftfeuchtigkeit. Heiß und schwül — die Verdunstung arbeitet gegen dich. Als Ausgangspunkt: etwa alle 15 Minuten, also ungefähr alle drei Kilometer, ein paar Schlucke — und dann nach Durst und Schweißmenge anpassen. So weit das Briefing. Tipp auf dem Display auf Aufwärmen starten, dann machen wir uns locker.“", "r21": "WHY · <b>Name deines Stadtteils + Live-Wetter von Open-Meteo</b>, dazu ein Trinkplan passend zu Temperatur und Luftfeuchtigkeit. An heißen Tagen kommen die Trinkerinnerungen beim Laufen automatisch öfter. Wetteranzeige und Aufwärm-Timer sind gratis, <b>vorgelesen</b> bekommst du diesen Text mit dem Abo", "r22": "Hinweis: Fürs Wetter gehen gerundete Koordinaten an Open-Meteo, für den Namen deines Stadtteils deine aktuellen Koordinaten an die Ortungsdienste von Apple, jeweils nur in diesem Moment.", "r23": "SEGMENT 01 — 0.0 → 1.0 KM", "r24": "Du musst nichts drücken.<br><span class=\"outline\">Lauf los, Runvis merkt es</span>", "r25": "Nach dem Aufwärmen läufst du einfach los. Runvis <b>erkennt den Lauf von selbst</b> und startet Aufzeichnung und Coaching.", "r26": "„Dein Zustandsbriefing für heute. Letzte Nacht 7 Stunden 24 Minuten Schlaf. Dein Ruhepuls liegt unter deinem Üblichen — ein gutes Zeichen.“", "r27": "WHY · Am Rhythmus des Beschleunigungssensors am Handgelenk <b>erkennt Runvis den Lauf automatisch</b> und startet die Aufzeichnung (gratis) · Das Zustands-Briefing kommt 8 Sekunden nach dem Start, aber nur, wenn dein Ruhepuls 5 über oder 3 unter deinem Normalwert liegt oder du weniger als 6 Stunden geschlafen hast. An normalen Tagen sagt der Coach dazu nichts", "r28": "−4 (UNTER NORMAL)", "r29": "SEGMENT 02 — 1.0 → 2.5 KM · ANSTIEG", "r3": "START", "r30": "Anstiege, die du <span class=\"grad\">vorher kennst</span>,<br>verlieren ihren Schrecken", "r31": "Lade die GPX-Strecke deines Wettkampfs, und Runvis kündigt dir <b>den Anstieg an, den du noch gar nicht siehst</b>.", "r32": "„In 300 Metern beginnt ein Anstieg über 800 Meter. Durchschnittlich 4 Prozent Steigung. Verkürze den Schritt und halte den Rhythmus.“", "r33": "WHY · Runvis liest das Höhenprofil der Strecke im Voraus. Mit Coach sagt dir das <b>steigungsbereinigte Tempo</b> am Anstieg auch, ob deine Geschwindigkeit gerade passt", "r34": "SEGMENT 03 — 3.0 → 4.0 KM · ERMÜDUNG", "r35": "Wenn es hart wird,<br>coacht Runvis <span class=\"outline\">mit Messwerten</span>", "r36": "Nicht „Deine Haltung ist schlecht“, sondern ein Technik-Hinweis, der sagt, <b>was sich wie stark</b> verändert hat.", "r37": "„Deine Schritte sind 7 Prozent langsamer und dein Bodenkontakt 10 Prozent länger als am Start. Verkürze den Schritt — die Frequenz kommt zurück und die Technik mit ihr.“", "r38": "WHY · Der Technik-Hinweis ist ein anderer als der zur Schrittlänge und hat eigene Regeln · Uhren, die Bodenkontakt und vertikale Bewegung messen: Von Schrittfrequenz, Bodenkontakt und vertikaler Bewegung <b>geraten mindestens zwei gemeinsam aus dem Tritt</b> oder einer deutlich, und das 30 Sekunden lang · Uhren, die nur die Schrittfrequenz messen: 6 % weniger Schrittfrequenz, 60 Sekunden lang · in beiden Fällen nur auf flacher Strecke bei gleichmäßigem Tempo · der Schalter „Lauftechnik“ in den Einstellungen schaltet Technik- und Schrittlängen-Hinweis gemeinsam ein · einmal gesagt, meldet sich der Coach erst wieder, wenn sich die Abweichung gelegt hat", "r39": "„Gut — deine Haltung kommt zurück. Bleib genau bei diesem Gefühl, nur noch ein bisschen.“", "r4": "BRIEFING", "r40": "WHY · Nur in Läufen, in denen du <b>die Warnung wirklich gehört hast</b> · einmal, frühestens 2 Minuten nach der Warnung und nur, wenn die Abweichung deutlich kleiner geworden ist als an ihrem Höhepunkt. Hat die Abstandsregel die Warnung zurückgehalten, gibt es auch kein Lob", "r41": "SEGMENT 04 — 4.0 → 4.5 KM · GEHPAUSE", "r42": "Gehen ist auch<br><span class=\"grad\">Teil des Trainings</span>", "r43": "Bist du platt, geh ruhig. Runvis meckert nicht, wenn du gehst, sondern <b>begleitet deine Erholung</b>.", "r44": "„Du gehst jetzt — kurz durchatmen ist eine gute Entscheidung. Lauf wieder locker los, wenn es sich gut anfühlt, oder geh weiter, wenn du das brauchst. Ich sage Bescheid, wenn dein Puls auf Zone eins fällt.“", "r45": "WHY · Runvis erkennt Gehen, wenn dein Tempo auf Gehniveau fällt und <b>die Schrittfrequenz 8 Sekunden lang unter 130</b> bleibt. Nur draußen mit GPS, nach den ersten 5 Minuten und nur bei freien Läufen ohne festen Plan · Beginnt das Gehen, werden noch wartende Lauf-Ansagen verworfen", "r46": "138 ← jetzt", "r47": "WARTET…", "r48": "„Dein Puls hat sich erholt. Wieder locker antraben? Fang ruhig an.“", "r49": "WHY · Beim Gehen meldet sich der Coach <b>bei jeder Zone, um die dein Puls sinkt</b>. Bei Zone 1 sagt er dir, dass du wieder loslaufen kannst. So <b>hörst du, wie du dich erholst</b>", "r5": "LOSLAUFEN", "r50": "FINISH — 5.0 KM · MISSION COMPLETE", "r51": "Der Lauf ist vorbei,<br>das Coaching geht <span class=\"grad\">jetzt erst los</span>", "r52": "Sobald der Lauf gespeichert ist, kommen Pulszonen, Trainingslast und Beobachtungen zu deiner Technik, dazu eine <b>Coaching-Zusammenfassung für den nächsten Lauf</b>. Bis hierhin ist alles gratis. Wenn du willst, exportierst du mit einem Tipp noch einen Bericht für die KI, die du nutzt.", "r53": "Distanz · Zeit", "r54": "Ø Pace · Puls", "r55": "Trainingslast", "r56": "TRIMP 54 · Drift +1,8 %", "r57": "Ein Satz vom Coach", "r58": "Die Herzfrequenz-Effizienz hielt bis in die zweite Hälfte.", "r59": "Export", "r6": "ANSTIEG", "r60": "✨ Für KI-Analyse · GPX", "r62": "Alle Funktionen ansehen", "r63": "Zahlen und Ansagen auf dieser Seite sind Beispiele, die zeigen, wie die echte App arbeitet. Alle Werte und Hinweise sind Orientierungswerte auf Basis allgemeiner sportwissenschaftlicher Formeln und keine medizinische Beratung.<br>Kontakt: <a href=\"mailto:help@runvis.app\" style=\"color:var(--dim)\">help@runvis.app</a> · © 2026 Runvis · Apple Watch ist eine Marke der Apple Inc.", "r7": "TIEFPUNKT", "r8": "ERHOLUNG", "r9": "ZIEL", "sc.note": "Die Screenshots auf dieser Seite (5 vom iPhone, 6 von der Apple Watch) sind echte Aufnahmen der App, eingestellt auf Deutsch. Die Bildschirme beim Laufen stammen aus einem echten Lauf. Die App wird seitdem weiter verbessert, deine Version kann also neuer sein als das, was du hier siehst.", "sc.note.s": "Echter Bildschirm der App, aufgenommen auf Deutsch.", "t160": "Einladung zur Beta anfordern", "t161": "Was wir erfassen", "t162": "Aufbewahrungsdauer", "t163": "Datenschutzerklärung", "t164": "Nutzungsbedingungen", "t165": "help@runvis.app", "t166": "Alle Werte und Hinweise von Runvis sind Referenzinformationen auf Basis allgemeiner sportwissenschaftlicher Formeln; sie sind keine medizinische Beratung und bewerten nicht deinen Gesundheitszustand. Bei Symptomen wie Brustschmerzen oder Schwindel brich das Training ab und wende dich an eine Fachperson. Apple Watch ist eine Marke von Apple Inc. Runvis ist eine unabhängige App und steht in keiner Verbindung zu Apple.", "tm.back": "← Zurück zu Runvis", "tm.h1": "Nutzungsbedingungen", "tm.legalNote": "Die koreanische Fassung ist die rechtsverbindliche Version. Andere Sprachen sind Übersetzungen zum besseren Verständnis; bei Auslegungsunterschieden gilt die koreanische Fassung. Kontakt: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "tm.meta.desc": "Nutzungsbedingungen von Runvis — Abos und Lifetime-Lizenz, automatische Verlängerung und Kündigung, Sicherheitshinweise und Haftungsgrenzen.", "tm.meta.title": "Nutzungsbedingungen — Runvis", "tm.s1.h": "1. Über den Dienst", "tm.s1.p": "Runvis ist eine Lauf-Tracking- und Coaching-App für Apple Watch und iPhone. GPS-Aufzeichnung, Runden, Speichern in Apple Health, das Durchsehen deiner Läufe, die Planansicht, der ausführliche Laufbericht und der Aufwärmbildschirm sind kostenlos. Sprachcoaching zu Technik, Erholung und Motivation, die abschnittsweise Ausführung des Trainingsplans samt Plan-Score, die Tiefenanalyse, die Rennstrategie und die wöchentliche Coach-Zusammenfassung werden über ein In-App-Abo oder eine Lifetime-Lizenz bereitgestellt. Runvis legt kein Konto an und betreibt keinen eigenen Server.", "tm.s2.h": "2. Abonnements", "tm.s2.li1": "Zahlung, Verlängerung und Kündigung laufen über dein Apple-App-Store-Konto und richten sich nach Apples Standard-Abobedingungen", "tm.s2.li2": "Monats- und Jahresabos verlängern sich <b>automatisch</b>. Kündigst du nicht mindestens <b>24 Stunden vor</b> Ende des laufenden Zeitraums, verlängert sich das Abo, und die Gebühr wird innerhalb der letzten 24 Stunden des Zeitraums über dein Apple-Konto abgerechnet", "tm.s2.li3": "Wird eine kostenlose Testphase angeboten, geht sie in ein kostenpflichtiges Abo über und wird berechnet, sofern du nicht mindestens 24 Stunden vor Ende kündigst. Ob eine Testphase angeboten wird, entscheidet Apple anhand der Berechtigung deines Kontos; sie erscheint nur dann im Kaufbildschirm", "tm.s2.li4": "Du kannst jederzeit unter iOS-Einstellungen → Apple-Account → Abonnements kündigen und behältst den Zugang bis zum Ende des bereits bezahlten Zeitraums", "tm.s2.li5": "Monats- und Jahresabo sind nicht von Apples Familienfreigabe abgedeckt. Das einzige Produkt, das eine Familiengruppe teilen kann, ist der lebenslange Zugang aus Abschnitt 3", "tm.s2.li6": "Rückerstattungen richten sich nach Apples Rückerstattungsrichtlinie und -verfahren", "tm.s3.h": "3. Lifetime-Lizenz", "tm.s3.li1": "Die Lifetime-Lizenz ist ein <b>einmalig bezahltes, nicht verbrauchbares Produkt</b> ohne automatische Verlängerung. Sie schaltet dieselben Coaching-Funktionen frei wie ein Abo", "tm.s3.li2": "Der aktuelle Preis ist ein <b>Einführungspreis</b> und kann später steigen. Eine Erhöhung gilt <b>nur für spätere Käufe</b>; eine bereits gekaufte Lizenz wird nie erneut belastet", "tm.s3.li3": "Der lebenslange Zugang ist von Apples Familienfreigabe abgedeckt, sodass auch die Mitglieder deiner Familiengruppe ihn nutzen können — keines der Abo-Produkte ist teilbar", "tm.s3.li4": "Da Runvis kein Konto anlegt, stellst du die Lizenz auf einem neuen Gerät oder nach einer Neuinstallation über <b>Käufe wiederherstellen</b> im Kaufbildschirm wieder her. Das funktioniert nur mit dem Apple-Konto, mit dem gekauft wurde", "tm.s3.li5": "Die Lifetime-Lizenz gilt, solange die Runvis-App im App Store angeboten wird. Wird der Dienst eingestellt, gilt zusätzlich die Klausel zu den Grenzen des Dienstes in Abschnitt 5", "tm.s3.li6": "Rückerstattungen richten sich nach Apples Rückerstattungsrichtlinie und -verfahren", "tm.s3.li7": "Das Trinkgeld (Kaffee, Mittagessen, Herz) ist ein <b>einmaliges Dankeschön</b> und schaltet keinerlei Funktionen frei — es ersetzt weder ein Abo noch die Lifetime-Lizenz", "tm.s4.h": "4. Deine Verantwortung", "tm.s4.li1": "Trainiere nach eigenem Ermessen und in eigener Verantwortung und berücksichtige dabei deinen Gesundheitszustand", "tm.s4.li2": "Achte beim Laufen im Freien auf Straßen oder Bahnen jederzeit auf Verkehr und Umgebung und nutze die Sprachansagen nur so laut, dass Umgebungsgeräusche hörbar bleiben", "tm.s4.li3": "Bei Symptomen wie Brustschmerz, Schwindel oder Atemnot brich das Training sofort ab und wende dich an Fachpersonal", "tm.s5.h": "5. Grenzen des Dienstes und Haftungsausschluss", "tm.s5.li1": "Alle Zahlen, Prognosen und Coaching-Hinweise in Runvis sind <b>Informationen zur Orientierung</b> auf Basis veröffentlichter sportwissenschaftlicher Formeln und keine medizinische Diagnose, Behandlung oder Verordnung", "tm.s5.li2": "Bauartbedingt können Herzfrequenz-, GPS- und Laufdynamikmessungen fehlerbehaftet sein; ihre Genauigkeit wird nicht zugesichert", "tm.s5.li3": "Für die Folgen eines Trainings auf Basis dieser Referenzinformationen (Leistungsveränderungen, Verletzungen usw.) übernimmt der Entwickler keine rechtliche Haftung, ausgenommen Schäden durch Vorsatz oder grobe Fahrlässigkeit", "tm.s5.li4": "Der Dienst wird „wie besehen“ bereitgestellt; einzelne Funktionen können sich durch Änderungen der Apple-Plattform oder externer APIs (z. B. Wetter) ändern oder entfallen", "tm.s6.h": "6. Geistiges Eigentum", "tm.s6.p": "Design, Texte und Code der App und der Website gehören dem Entwickler. Deine Trainings- und Gesundheitsdaten gehören vollständig dir.", "tm.s7.h": "7. Änderungen dieser Bedingungen", "tm.s7.p": "Bei Änderungen dieser Bedingungen wird das Datum auf dieser Seite aktualisiert; wesentliche Änderungen werden in der App bekannt gegeben.", "tm.s8.h": "8. Kontakt", "tm.s8.p": "<a href=\"mailto:help@runvis.app\">help@runvis.app</a> · Wie deine Daten verarbeitet werden, steht in der <a href=\"privacy.html\">Datenschutzerklärung</a>.", "tm.updated": "Gültig ab: 6. September 2026 · Version 1.2", "vchip0": "25 Sekunden schneller als das Ziel", "vchip1": "In 300 Meter beginnt ein Anstieg über 800 Meter. Durchschnittlich 4 Prozent. Verkürze den Schritt und halte den Rhythmus.", "vchip2": "Die Schrittfrequenz liegt 5 Prozent unter deiner Basis – verkürzen wir den Schritt ein wenig?", "vchip3": "Dein Puls ist bis auf Zone 3 gefallen. Du erholst dich gut — fast geschafft.", "n.why.cost": "Du musst kein neues Gerät kaufen. Runvis nutzt die Apple Watch, die du schon trägst. Du zahlst nur für den Coach, im koreanischen App Store wahlweise ₩1,900 im Monat, ₩15,000 im Jahr oder einmalig ₩39,000 für den lebenslangen Zugang. Eine Laufuhr braucht jede Person für sich. Der lebenslange Zugang gilt mit einem Kauf auch für deine Familienfreigabe-Gruppe bei Apple. Was gleich ist und was anders als bei einer Laufuhr: <a href=\"how-it-works.html#versus\">der Vergleich, Wert für Wert</a>.", "n.live.q.sum": "Beim lockeren Lauf spricht der Coach höchstens 8-mal in 30 Minuten, beim Tempolauf und im Wettkampf höchstens 6-mal. Zwischen zwei Ansagen liegen mindestens 45 Sekunden. Splits kommen immer, unabhängig von diesen Grenzen. Ansagen vor Anstiegen zählen nicht zur Obergrenze, halten aber 45 Sekunden Abstand zur letzten Ansage. Bei Intervallen gibt es keine feste Zahl: Wie oft der Coach spricht, hängt davon ab, welche Ansagen du eingeschaltet hast.", "pl.month": "Monatlich", "pl.year": "Jährlich", "pl.life": "Lebenslang", "pr.year": "₩15,000", "pr.life": "₩39,000", "pr.monthn": "Verlängert sich monatlich · jederzeit kündbar", "pr.yearn": "Rund ₩1,250 im Monat · etwa 34 % günstiger als monatlich", "pr.lifen": "Einmalkauf · verlängert sich nicht · mit Familienfreigabe", "n.price.moreh": "Preise in anderen Ländern, Ersparnis und ab wann sich „Lebenslang“ lohnt", "n.price.nowh": "Sofort freigeschaltet, sobald du abonnierst", "n.price.laterh": "Füllt sich, je mehr du läufst", "n.price.f6": "Tipp-Karte nach dem Lauf", "n.beta.order": "Einen Starttermin gibt es noch nicht. Die Einladungen gehen in der Reihenfolge der Anmeldungen raus. Da Apple bei TestFlight höchstens 10.000 externe Tester zulässt, gilt: Je früher du dich einträgst, desto früher kommt deine Einladung.", "hz.h": "Gleich ausprobieren: deine 5 Pulszonen", "hz.p": "Das ist dieselbe Karvonen-Formel, die Runvis für die Coach-Stimme nutzt. Die App aktualisiert die Werte laufend mit deinem Ruhepuls der letzten 7 Tage aus der Health App und dem höchsten Puls, der tatsächlich aufgezeichnet wurde. Gerechnet wird aber genau so wie hier.", "hz.age": "Alter", "hz.rest": "Ruhepuls", "hz.max": "Maximalpuls (leer lassen, wenn du ihn nicht kennst)", "hz.bpm": "bpm", "hz.note": "Untergrenze der Zone = (Maximalpuls − Ruhepuls) × 50/60/70/80/90 % + Ruhepuls. Ohne Maximalpuls wird er als 208 − 0,7 × Alter geschätzt. Eine Rechnung zur Orientierung, keine medizinische Beratung.", "hz.bad": "Dein Ruhepuls liegt zu nah am Maximalpuls, um Zonen zu bilden.", "hz.z1": "Z1 Regeneration", "hz.z2": "Z2 Aerob", "hz.z3": "Z3 Tempo", "hz.z4": "Z4 VO2max", "hz.z5": "Z5 Anaerob", "hz.maxtyped": "Mit deinem eingegebenen Maximalpuls", "hz.maxest": "Maximalpuls geschätzt mit 208 − 0,7 × Alter", "form.okaddr": "Eingetragene Adresse", "r.cue": "Scrollen und los ▾", "n.today.mininote": "Die Zahlen in diesen drei Feldern sind Beispiele und zeigen nur den Aufbau. Der Screenshot daneben stammt aus der echten App.", "pr.approx2": "Die Umrechnung oben soll dir nur ein Gefühl für die Größenordnung geben. Sie ist nicht der Betrag, den du zahlst. Apple rechnet nicht mit dem Wechselkurs, sondern mit Preisstufen, die für jedes Land eigens festgelegt sind. Der echte Preis kann also etwas höher oder niedriger liegen. Sobald die Preise für andere Länder feststehen, findest du hier die echten Beträge. Der Kaufbildschirm der App rät nicht: Er zeigt genau den Preis, den der Store für dein Land nennt.", "hw.meta.title": "Gleich oder anders als Garmin und Coros? Rechenwege Wert für Wert | Runvis", "hw.meta.desc": "Laufuhren wie Garmin Forerunner oder Coros und die Apple Watch im Vergleich, Wert für Wert. Dazu, wie Runvis Trainingslast, Erholungszeit und Laktatschwelle berechnet. Außerdem: wie oft der Coach in 30 Minuten spricht, ein Pulszonen-Rechner, 13 Seouler Strecken als GPX und der Ablauf der Beta.", "hw.h1": "Rechenwege und Tools", "hw.intro": "Hier steht ausführlich, was die Startseite in einem Satz sagt. Lesen und ausprobieren kannst du alles sofort, ohne Anmeldung und ohne App.", "hw.s1.h": "Wie oft der Coach spricht und welche Ausnahmen gelten", "hw.vs.h": "Laufuhren wie Garmin Forerunner oder Coros: Was ist gleich, was ist anders?", "hw.vs.p": "Trainingslast, Erholungszeit, geschätzte Laktatschwelle, Tempoplan fürs Rennen: Für diese Werte braucht man angeblich eine Laufuhr wie eine Garmin Forerunner oder eine Coros. Es gibt Hersteller, die solche Werte längst in ihren eigenen Uhren berechnen. Auf der Apple Watch hat das bisher nur niemand gemacht. Runvis berechnet dieselben Werte aus Puls, GPS und Höhe, die deine Apple Watch sowieso aufzeichnet. Die Formeln der Laufuhren sind nicht öffentlich, deshalb behauptet Runvis nicht, es seien dieselben. Dafür sind alle Formeln, die Runvis nutzt, veröffentlicht und haben einen Namen. Welche das sind, steht unten. In der App tippst du einen Wert an und siehst, was er bedeutet, wie er berechnet wird und was bei dir normal ist.", "hw.vs.th1": "Kennzahl", "hw.vs.th2": "So rechnet Runvis, und so heißt die Formel", "hw.vs.r12a": "Ausdauer-Trainingsumfang", "hw.vs.r12b": "Ein Wert von 0 bis 100 aus drei Größen der letzten 28 Tage, gewichtet im Verhältnis 45 : 35 : 20: Wochenkilometer (volle Punktzahl bei 80 km pro Woche), dein längster Lauf (volle Punktzahl bei 30 km) und die Zahl der Wochen mit Lauf in den letzten 4 Wochen. Das ist keine Note für dich, sondern zeigt, wie viel Training dein Körper gerade gesammelt hat. Reichen die Daten nicht, erfindet Runvis keinen Wert: Er bleibt bei 0, und auf dem Bildschirm steht, was noch fehlt.", "hw.vs.r13a": "Beinbelastung", "hw.vs.r13b": "Die Belastung, die ein Lauf in deinen Beinen hinterlässt, gezählt in Kilometer-Äquivalenten. 1 km locker in der Ebene = 1,0. Dieselbe Strecke schnell, bergauf oder bergab zählt mehr. Pro Lauf gilt: Distanz × Intensitätsmultiplikator × Steigungsmultiplikator. Der Intensitätsmultiplikator richtet sich nach der Geschwindigkeit, nicht nach dem Puls (gemessen an deinem lockeren Tempo und deinem Schwellentempo): locker oder langsamer 1,0, an der Schwelle 1,35, schneller bis zu 1,6. Der Steigungsmultiplikator ist bergauf tatsächliches Tempo ÷ steigungsbereinigtes Tempo (höchstens 1,6). Bergab zählt er mit 1 + 1,2 × (1 − dieses Verhältnis) stärker (höchstens 2,0), denn bergab ist es weniger anstrengend, der Aufprall aber härter. Der kurzfristige Wert ist ein täglicher exponentiell gewichteter gleitender Durchschnitt (EWMA, Zeitkonstante 7 Tage) und liegt damit auf dem Niveau eines Tagesdurchschnitts (bei regelmäßigem Laufen etwa Wochensumme ÷ 7). Der Wochenwert ist die einfache Summe der Woche. Angezeigt wird er auf der Kachel im Bericht und in den Laufdetails (neben „Trainingsbelastung (TRIMP)“), jeweils neben der tatsächlichen Distanz. Laufdynamik und Gehabschnitte fließen noch nicht ein. Garmin hat seine Formel nicht veröffentlicht. Die Multiplikatoren oben sind Orientierungswerte, die Runvis anhand veröffentlichter Literatur festgelegt hat.", "hw.vs.r1a": "Trainingslast · Frische (TSB)", "hw.vs.r1b": "Banister-TRIMP fließt in Coggans exponentielle 42- und 7-Tage-Durchschnitte (CTL und ATL). Der TSB von heute ist CTL minus ATL von gestern (nach Coggans Definition ändert die Belastung von heute den TSB von heute nicht).", "hw.vs.r2a": "Erholungszeit", "hw.vs.r2b": "Geschätzt aus dem TRIMP deines letzten Laufs, deinem aktuellen TSB und deinem HRV-Trend. Auf dem Bildschirm ist sie auch als Schätzung gekennzeichnet.", "hw.vs.r3a": "Laktatschwelle (geschätzt)", "hw.vs.r3b": "Tempo und Puls deiner 30-Minuten-Bestleistung (oder 20-Minuten-Bestleistung) der letzten 90 Tage, gelaufen mit mindestens 85 % des Maximalpulses. Eine Schätzung aus deinen Läufen, keine Blutabnahme im Labor.", "hw.vs.r4a": "Rennzeitprognose · Tempoplan pro Abschnitt", "hw.vs.r4b": "Prognose mit der Riegel-Formel und dem Runvis-Fitnessindex. Mit der GPX einer Strecke verteilt Runvis das Tempo passend zum Höhenprofil auf die einzelnen Abschnitte.", "hw.vs.r5a": "Steigungsbereinigtes Tempo (GAP)", "hw.vs.r5b": "Basiert auf der Kurve des Energieverbrauchs beim Laufen von Minetti (2002). Bergauf und bergab werden getrennt berechnet.", "hw.vs.r6a": "Die 5 Pulszonen", "hw.vs.r6b": "Karvonen-Methode (Herzfrequenzreserve). Ist dein Maximalpuls unbekannt, wird er als 208 − 0,7 × Alter geschätzt. Der Rechner unten nutzt dieselbe Formel.", "hw.vs.note": "Auch das gehört dazu: was Laufuhren haben und Runvis noch nicht. Komplikationen fürs Zifferblatt, ein Widget für den Home-Bildschirm des iPhone und Live-Aktivitäten sind in dieser Version nicht dabei. Alle Werte oben dienen der Orientierung und sind keine medizinische Beratung."};
